package org.apache.kafka.clients;
import java.net.InetAddress;
import org.apache.kafka.common.message.ProduceResponseData;
import org.apache.kafka.common.requests.ProduceResponse;
import org.apache.kafka.common.utils.LogContext;

public final class ProduceThrottleReference {
    private static void require(boolean condition) {
        if (!condition) throw new AssertionError("Apache throttle contract changed");
    }
    public static void main(String[] args) {
        ProduceResponse response = new ProduceResponse(new ProduceResponseData());
        for (short version = 3; version <= 12; version++) {
            boolean result = response.shouldClientThrottle(version);
            require(result == (version >= 6));
            System.out.println("version=" + version + " client_throttle=" + result);
        }
        ClusterConnectionStates states = new ClusterConnectionStates(1, 1, 1000, 1000,
                new LogContext(), host -> new InetAddress[] {InetAddress.getLoopbackAddress()});
        states.connecting("1", 1000, "localhost");
        states.ready("1");
        states.connecting("2", 1000, "localhost");
        states.ready("2");
        states.throttle("1", 1400);
        require(states.throttleDelayMs("1", 1000) == 400);
        require(states.throttleDelayMs("2", 1000) == 0);
        require(!states.isReady("1", 1000) && states.isReady("2", 1000));
        states.throttle("1", 1100);
        states.throttle("1", 1000);
        require(states.throttleDelayMs("1", 1000) == 400);
        states.throttle("1", 1700);
        require(states.throttleDelayMs("1", 1000) == 700);
        require(states.isReady("1", 1700));
        states.disconnected("1", 1100);
        require(states.throttleDelayMs("1", 1100) == 600);
        System.out.println("node_isolation=pass max_interval=pass expiry=pass reconnect_interval=pass");
    }
}
